                 mutex: 'ai_validating', mutexAmong: ['pr_approved'] },
        localAction: 'validate_pr', skipIfValidatedHead: true, redHeadSkip: true,
        deferRedHead: true, limit: 1, id: 'validate-armed' };

    var REVIEW_RULE = { source: 'github',
