        assert.deepEqual(reviewRefs, ['ai/x-81', 'ai/x-82'], 'the two oldest reviews win the FIFO');
    });

    test('UT-7 (AC10): cap 3, no approved candidate — 3 reviews (the reservation is released)', function () {
        var sm = reviewTick({
            github: { items: function (rule) {
