function holdDispatchForPushSuite(repoInfo, ticket, key, headSha) {
    var bodies = prCommentBodiesSafe(repoInfo, ticket.prNumber);
    var last = invisibleRequiredModule.lastResetAtMs(bodies);
    if (last === null) return false;
